fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // Check that each pile has at least m cookies for the special guests
    if a < m || b < m {
        return false;
    }

    // Promote to u16 to avoid overflow when adding
    let total_available = a as u16 + b as u16;
    let total_required = n as u16 + 2 * (m as u16);

    // Check that the total available cookies suffice for all guests
    total_available >= total_required
}

